module secure_network(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [2:0] p,\n    input [7:0] insecure_mask,\n    input [7:0] edge_valid,\n    input [2:0] edge_u [27:0],\n    input [2:0] edge_v [27:0],\n    input [9:0] edge_w [27:0],\n    output reg [15:0] result,\n    output reg done,\n    output reg impossible\n);\n\n    localparam IDLE = 4'd0;\n    localparam INIT = 4'd1;\n    localparam PREP_SUBSET = 4'd2;\n    localparam CHECK_DEG = 4'd3;\n    localparam CHECK_CONN = 4'd4;\n    localparam VERIFY_CONN = 4'd5;\n    localparam CALC_COST = 4'd6;\n    localparam UPDATE_BEST = 4'd7;\n    localparam NEXT_SUBSET = 4'd8;\n    localparam DONE = 4'd9;\n\n    reg [3:0] state, next_state;\n    reg [15:0] best_cost, next_best_cost;\n    reg best_found, next_best_found;\n    reg [15:0] current_cost;\n\n    reg [4:0] num_valid_edges;\n    reg [4:0] edge_idx;\n    reg [2:0] comp_u [15:0];\n    reg [2:0] comp_v [15:0];\n    reg [9:0] comp_w [15:0];\n\n    reg [15:0] subset_mask;\n    reg [15:0] max_subset;\n\n    reg [4:0] temp_popcount;\n    reg temp_invalid_node;\n\n    reg [2:0] node_degree [7:0];\n    reg [2:0] node_check_idx;\n\n    reg [2:0] bfs_queue [7:0];\n    reg [2:0] bfs_head, bfs_tail, bfs_node;\n    reg [2:0] visited_count;\n    reg [7:0] visited_nodes;\n\n    integer i;\n\n    always @(*) begin\n        next_state = state;\n        next_best_cost = best_cost;\n        next_best_found = best_found;\n        done = 1'b0;\n        impossible = 1'b0;\n        result = best_cost;\n\n        case (state)\n            IDLE: if (start) next_state = INIT;\n            INIT: begin\n                if (edge_idx >= 28) begin\n                    if (num_valid_edges == 0) next_state = DONE;\n                    else next_state = PREP_SUBSET;\n                end\n            end\n            PREP_SUBSET: begin\n                if (subset_mask > max_subset) next_state = DONE;\n                else next_state = CHECK_DEG;\n            end\n            CHECK_DEG: begin\n                if (edge_idx >= num_valid_edges) begin\n                    if (temp_invalid_node) next_state = NEXT_SUBSET;\n                    else if (temp_popcount != (n - 1)) next_state = NEXT_SUBSET;\n                    else next_state = CHECK_CONN;\n                end\n            end\n            CHECK_CONN: begin\n                next_state = VERIFY_CONN;\n            end\n            VERIFY_CONN: begin\n                if (visited_count == n) next_state = CALC_COST;\n                else if (bfs_head == bfs_tail) next_state = NEXT_SUBSET;\n                else next_state = VERIFY_CONN;\n            end\n            CALC_COST: begin\n                if (edge_idx >= num_valid_edges) next_state = UPDATE_BEST;\n            end\n            UPDATE_BEST: begin\n                next_state = NEXT_SUBSET;\n            end\n            NEXT_SUBSET: begin\n                next_state = PREP_SUBSET;\n            end\n            DONE: begin\n                done = 1'b1;\n                if (!best_found && n > 1) impossible = 1'b1;\n                else impossible = 1'b0;\n            end\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            best_cost <= 16'hFFFF;\n            best_found <= 1'b0;\n            edge_idx <= 0;\n            num_valid_edges <= 0;\n            subset_mask <= 16'h0001;\n            max_subset <= 16'h0000;\n            temp_popcount <= 0;\n            temp_invalid_node <= 0;\n            current_cost <= 0;\n            for (i=0; i<8; i=i+1) begin\n                node_degree[i] <= 0;\n                visited_nodes[i] <= 0;\n                bfs_queue[i] <= 0;\n            end\n        end else begin\n            state <= next_state;\n            best_cost <= next_best_cost;\n            best_found <= next_best_found;\n\n            case (state)\n                IDLE: begin\n                    subset_mask <= 16'h0001;\n                    num_valid_edges <= 0;\n                    edge_idx <= 0;\n                end\n\n                INIT: begin\n                    if (edge_idx < 28) begin\n                        if (edge_idx < 8) begin\n                            if (edge_valid[edge_idx]) begin\n                                if (num_valid_edges < 16) begin\n                                    comp_u[num_valid_edges] <= edge_u[edge_idx];\n                                    comp_v[num_valid_edges] <= edge_v[edge_idx];\n                                    comp_w[num_valid_edges] <= edge_w[edge_idx];\n                                    num_valid_edges <= num_valid_edges + 1;\n                                end\n                            end\n                        end\n                        edge_idx <= edge_idx + 1;\n                    end\n                end\n\n                PREP_SUBSET: begin\n                    max_subset <= (num_valid_edges == 0) ? 0 : ((1 << num_valid_edges) - 1);\n                    temp_popcount <= 0;\n                    temp_invalid_node <= 1'b0;\n                    edge_idx <= 0;\n                    node_check_idx <= 0;\n                    current_cost <= 0;\n                    for (i=0; i<8; i=i+1) node_degree[i] <= 0;\n                    visited_nodes <= 0;\n                    visited_count <= 0;\n                    bfs_head <= 0;\n                    bfs_tail <= 0;\n                end\n\n                CHECK_DEG: begin\n                    if (edge_idx < num_valid_edges) begin\n                        if (subset_mask[edge_idx]) begin\n                            temp_popcount <= temp_popcount + 1;\n                            node_degree[comp_u[edge_idx]] <= node_degree[comp_u[edge_idx]] + 1;\n                            node_degree[comp_v[edge_idx]] <= node_degree[comp_v[edge_idx]] + 1;\n                        end\n                        edge_idx <= edge_idx + 1;\n                    end else begin\n                        if (node_check_idx < n) begin\n                            if (insecure_mask[node_check_idx]) begin\n                                if (node_degree[node_check_idx] > 1) begin\n                                    temp_invalid_node <= 1'b1;\n                                end\n                            end\n                            node_check_idx <= node_check_idx + 1;\n                        end\n                    end\n                end\n\n                CHECK_CONN: begin\n                    if (n > 0 && temp_popcount == (n - 1) && !temp_invalid_node) begin\n                        visited_nodes[0] <= 1'b1;\n                        visited_count <= 1;\n                        bfs_queue[0] <= 0;\n                        bfs_head <= 1;\n                        bfs_tail <= 0;\n                        bfs_node <= 0;\n                        edge_idx <= 0;\n                    end\n                end\n\n                VERIFY_CONN: begin\n                    if (edge_idx < num_valid_edges) begin\n                        if (subset_mask[edge_idx]) begin\n                            if (comp_u[edge_idx] == bfs_node && !visited_nodes[comp_v[edge_idx]]) begin\n                                visited_nodes[comp_v[edge_idx]] <= 1'b1;\n                                visited_count <= visited_count + 1;\n                                bfs_queue[bfs_head] <= comp_v[edge_idx];\n                                bfs_head <= bfs_head + 1;\n                            end else if (comp_v[edge_idx] == bfs_node && !visited_nodes[comp_u[edge_idx]]) begin\n                                visited_nodes[comp_u[edge_idx]] <= 1'b1;\n                                visited_count <= visited_count + 1;\n                                bfs_queue[bfs_head] <= comp_u[edge_idx];\n                                bfs_head <= bfs_head + 1;\n                            end\n                        end\n                        edge_idx <= edge_idx + 1;\n                    end else begin\n                        if (bfs_head != bfs_tail) begin\n                            bfs_node <= bfs_queue[bfs_tail];\n                            bfs_tail <= bfs_tail + 1;\n                            edge_idx <= 0;\n                        end\n                    end\n                end\n\n                CALC_COST: begin\n                    if (edge_idx < num_valid_edges) begin\n                        if (subset_mask[edge_idx]) begin\n                            current_cost <= current_cost + comp_w[edge_idx];\n                        end\n                        edge_idx <= edge_idx + 1;\n                    end\n                end\n\n                UPDATE_BEST: begin\n                    if (current_cost < best_cost) begin\n                        best_cost <= current_cost;\n                        best_found <= 1'b1;\n                    end\n                end\n\n                NEXT_SUBSET: begin\n                    subset_mask <= subset_mask + 1;\n                end\n            endcase\n        end\n    end\nendmodule